import { TASHKENT_UTC_OFFSET_MINUTES, type BankDirection } from '@repo/shared';

// SYNTHETIC bank messages for the matcher tests (E-29): the STRUCTURE of the Uzcard bot
// (docs/05 §5), values generated by the test (amounts, balances, card endings, times). Never a
// real card ending, amount, balance, time, channel or name from a screenshot or a log.

const THOUSANDS = /\B(?=(\d{3})+$)/g;

/** "20 341.00 UZS" (Uzcard style) from tiyin. */
export function uzcardAmount(tiyin: bigint): string {
  const som = (tiyin / 100n).toString().replace(THOUSANDS, ' ');
  return `${som}.${(tiyin % 100n).toString().padStart(2, '0')} UZS`;
}

const two = (n: number): string => String(n).padStart(2, '0');

/** "DD.MM.YY HH:MM" in Asia/Tashkent for a UTC instant (minute precision, like the bot). */
export function uzcardTime(at: Date): string {
  const local = new Date(at.getTime() + TASHKENT_UTC_OFFSET_MINUTES * 60_000);
  const date = `${two(local.getUTCDate())}.${two(local.getUTCMonth() + 1)}.${two(local.getUTCFullYear() % 100)}`;
  return `${date} ${two(local.getUTCHours())}:${two(local.getUTCMinutes())}`;
}

export interface SyntheticMessage {
  readonly direction: BankDirection;
  readonly amountTiyin: bigint;
  readonly balanceAfterTiyin: bigint;
  readonly last4: string;
  readonly bankTxnAt: Date;
  /** null = no title line at all; undefined = the known title of the direction. */
  readonly title?: string | null;
}

export function uzcardText(message: SyntheticMessage): string {
  const credit = message.direction === 'CREDIT';
  const known = credit ? '🟢 Perevod na kartu' : '🔴 Pokupka';
  const title = message.title === undefined ? known : message.title;
  return [
    ...(title === null ? [] : [title]),
    `${credit ? '➕' : '➖'} ${uzcardAmount(message.amountTiyin)}`,
    `💳 ***${message.last4}`,
    '📍 TEST BANK P2P, UZ',
    `🕐 ${uzcardTime(message.bankTxnAt)}`,
    `💵 ${uzcardAmount(message.balanceAfterTiyin)}`,
  ].join('\n');
}
